[CmdletBinding()]
param(
    [ValidateSet('CreateKill','RecoverShutdown','OfflineCompact','Negative')]
    [string]$Phase,
    [Parameter(Mandatory)][string]$Executable,
    [Parameter(Mandatory)][string]$Bundle,
    [Parameter(Mandatory)][string]$DriveLetter,
    [Parameter(Mandatory)][string]$StateFile,
    [switch]$SafetyAcknowledged
)
$ErrorActionPreference='Stop'; Set-StrictMode -Version Latest
class M4LifecycleBlocked : System.Exception {
    M4LifecycleBlocked([string]$message) : base($message) {}
}
# This must remain the first executable decision: it intentionally does not
# resolve, create, or inspect any caller supplied path.
if(-not $SafetyAcknowledged){ Write-Output "M4 lifecycle $Phase BLOCKED: SafetyAcknowledged is required."; exit 77 }

$Size='64M'; $CheckpointSeconds='5'; $CheckpointDirtyMb='1'; $RamLimit='64M'
trap [M4LifecycleBlocked] { Write-Output "M4 lifecycle $Phase BLOCKED: $($_.Exception.Message)"; exit 77 }
function Block([string]$m){ throw [M4LifecycleBlocked]::new($m) }
function Need([bool]$ok,[string]$m){if(-not $ok){Block $m}}
function Inventory {
 $d=@(Get-CimInstance Win32_DiskDrive -ErrorAction Stop);$os=Get-CimInstance Win32_OperatingSystem -ErrorAction Stop
 $mappings=@(Get-Volume -ErrorAction Stop|?{$_.DriveLetter}|%{$letter=[string]$_.DriveLetter;$parts=@(Get-Partition -DriveLetter $letter -ErrorAction SilentlyContinue);$locations=$(if($parts.Count){@($parts|%{"$($_.DiskNumber):$($_.PartitionNumber)"}|sort)-join','}else{'none'});"$($letter.ToUpperInvariant()):|$($_.UniqueId)|$locations"}|sort)
 [ordered]@{boot_identity=([datetime]$os.LastBootUpTime).ToUniversalTime().ToString('o');stable_identities=@($d|%{"$($_.PNPDeviceID)|$($_.SerialNumber)|$($_.Model)|$($_.Size)"}|sort);aim_stable=@($d|?{$_.Model-match'(?i)Arsenal|AIM|ImDisk'}|%{"$($_.PNPDeviceID)|$($_.SerialNumber)|$($_.Model)|$($_.Size)"}|sort);physical_devices=@($d|%{"$($_.DeviceID)|$($_.PNPDeviceID)|$($_.Size)"}|sort);drive_mappings=$mappings}
}
function StableInventory($x){[ordered]@{stable_identities=@($x.stable_identities);aim_stable=@($x.aim_stable);physical_devices=@($x.physical_devices);drive_mappings=@($x.drive_mappings)}}
function Json($x){$x|ConvertTo-Json -Depth 12 -Compress}
function Same($a,$b){(Json $a) -ceq (Json $b)}
function EvidenceDir([string]$p){$d=Split-Path -Parent ([IO.Path]::GetFullPath($p));if(-not$d){Block 'StateFile must have an absolute parent directory.'};$d}
function PhasePath([string]$p){Join-Path (EvidenceDir $p) ("m4-lifecycle-$Phase.v1.json")}
function Hashes([string[]]$n){$h=[ordered]@{};foreach($x in $n){$p=Join-Path "$DriveLetter`:" $x;Need ([IO.File]::Exists($p)) "missing workload $x";$h[$x]=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash};$h}
function Commit { if($env:MYRD_M4_SOURCE_COMMIT -notmatch '^[0-9A-Fa-f]{40}$'){Block 'MYRD_M4_SOURCE_COMMIT must be an exact non-secret 40-hex host artifact marker.'};$env:MYRD_M4_SOURCE_COMMIT.ToLowerInvariant() }
function Args { @('run','--bundle',$Bundle,'--size',$Size,'--drive-letter',"$DriveLetter`:",'--checkpoint-seconds',$CheckpointSeconds,'--checkpoint-dirty-mb',$CheckpointDirtyMb,'--ram-limit',$RamLimit) }
function Write-New([string]$path,[string]$text){$stream=[IO.File]::Open($path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$writer=[IO.StreamWriter]::new($stream,[Text.UTF8Encoding]::new($false));$writer.Write($text);$writer.Flush();$writer.Dispose();$stream=$null}finally{if($null-ne$stream){$stream.Dispose()}}}
function Save($s){$j=Json $s;if($j-match'(?i)(password|private[ _-]?key|secret|token)'){throw 'unsafe evidence content'};$p=PhasePath $StateFile;Need(-not(Test-Path $p))"Refusing to overwrite immutable phase evidence: $p";Write-New $p ($j+[Environment]::NewLine)}
function Load([string]$name){$p=Join-Path (EvidenceDir $StateFile) "m4-lifecycle-$name.v1.json";Need ([IO.File]::Exists($p)) "missing $name evidence: $p";$raw=Get-Content $p -Raw -Encoding UTF8;Need($raw-notmatch'(?i)(password|private[ _-]?key|secret|token)')"unsafe $name evidence";$raw|ConvertFrom-Json}

# Bound child helper: independent asynchronous stream drains, exact process ID,
# finite waits, and exact-PID emergency cleanup only.  CREATE_NEW_PROCESS_GROUP
# makes CTRL_BREAK_EVENT targetable without a broad console broadcast.
Add-Type @'
using System; using System.IO; using System.Text; using System.Threading; using System.Runtime.InteropServices;
public sealed class M4Child : IDisposable {
 [StructLayout(LayoutKind.Sequential)] struct SA { public int nLength; public IntPtr lpSecurityDescriptor; [MarshalAs(UnmanagedType.Bool)] public bool bInheritHandle; }
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)] struct SI { public int cb; public IntPtr lpReserved,lpDesktop,lpTitle; public int dwX,dwY,dwXSize,dwYSize,dwXCountChars,dwYCountChars,dwFillAttribute,dwFlags; public short wShowWindow,cbReserved2; public IntPtr lpReserved2,hStdInput,hStdOutput,hStdError; }
 [StructLayout(LayoutKind.Sequential)] struct SIX { public SI StartupInfo; public IntPtr lpAttributeList; }
 [StructLayout(LayoutKind.Sequential)] struct PI { public IntPtr hProcess,hThread; public int pid,tid; }
 [DllImport("kernel32",SetLastError=true,CharSet=CharSet.Unicode)] static extern bool CreateProcess(string a,StringBuilder b,IntPtr c,IntPtr d,bool inherit,uint flags,IntPtr env,string dir,ref SIX si,out PI pi);
 [DllImport("kernel32",SetLastError=true)] static extern bool CreatePipe(out IntPtr r,out IntPtr w,ref SA a,int n);
 [DllImport("kernel32",SetLastError=true)] static extern IntPtr CreateFile(string n,uint a,uint s,ref SA sa,uint c,uint f,IntPtr t);
 [DllImport("kernel32",SetLastError=true)] static extern bool InitializeProcThreadAttributeList(IntPtr l,int c,int f,ref IntPtr n);
 [DllImport("kernel32",SetLastError=true)] static extern bool UpdateProcThreadAttribute(IntPtr l,uint f,IntPtr a,IntPtr v,IntPtr s,IntPtr p,IntPtr q);
 [DllImport("kernel32")] static extern void DeleteProcThreadAttributeList(IntPtr l);
 [DllImport("kernel32",SetLastError=true)] static extern bool SetHandleInformation(IntPtr h,uint m,uint f);
 [DllImport("kernel32",SetLastError=true)] static extern uint WaitForSingleObject(IntPtr h,uint ms);
 [DllImport("kernel32",SetLastError=true)] static extern bool GetExitCodeProcess(IntPtr h,out uint c);
 [DllImport("kernel32",SetLastError=true)] static extern bool TerminateProcess(IntPtr h,uint c);
 [DllImport("kernel32",SetLastError=true)] static extern bool CloseHandle(IntPtr h);
 [DllImport("kernel32",SetLastError=true)] static extern bool FreeConsole(); [DllImport("kernel32",SetLastError=true)] static extern bool AttachConsole(uint p); [DllImport("kernel32",SetLastError=true)] static extern bool SetConsoleCtrlHandler(IntPtr h,bool x); [DllImport("kernel32",SetLastError=true)] static extern bool GenerateConsoleCtrlEvent(uint e,uint g);
 const uint STARTF_USESTDHANDLES=0x100, CREATE_NEW_PROCESS_GROUP=0x200, EXTENDED_STARTUPINFO_PRESENT=0x80000, HANDLE_FLAG_INHERIT=1, CTRL_BREAK_EVENT=1, GENERIC_READ=0x80000000, OPEN_EXISTING=3, PROC_THREAD_ATTRIBUTE_HANDLE_LIST=0x20002;
 public readonly int Pid; IntPtr h; public readonly StringBuilder Out=new StringBuilder(),Err=new StringBuilder(); readonly Thread ot,et; volatile bool overflow,readFailure;
 static string Q(string s){var b=new StringBuilder("\"");int n=0;foreach(char c in s){if(c=='\\'){n++;continue;}if(c=='\"'){b.Append('\\',n*2+1).Append('\"');n=0;continue;}b.Append('\\',n).Append(c);n=0;}b.Append('\\',n*2).Append('\"');return b.ToString();}
 void Drain(Stream s,StringBuilder b){try{using(var r=new StreamReader(s,Encoding.UTF8,true)){char[] x=new char[1024];int n;while((n=r.Read(x,0,x.Length))>0){lock(b){int room=65536-b.Length;if(room>0)b.Append(x,0,Math.Min(room,n));if(n>room)overflow=true;}}}}catch{readFailure=true;}}
  public static M4Child Start(string exe,string[] args){SA sa=new SA{nLength=Marshal.SizeOf(typeof(SA)),bInheritHandle=true};IntPtr or=IntPtr.Zero,ow=IntPtr.Zero,er=IntPtr.Zero,ew=IntPtr.Zero,nul=IntPtr.Zero,list=IntPtr.Zero,handles=IntPtr.Zero;bool transferred=false;try{if(!CreatePipe(out or,out ow,ref sa,0)||!CreatePipe(out er,out ew,ref sa,0))throw new IOException("CreatePipe "+Marshal.GetLastWin32Error());bool nonInheritOut=SetHandleInformation(or,HANDLE_FLAG_INHERIT,0);int nonInheritOutError=Marshal.GetLastWin32Error();bool nonInheritErr=SetHandleInformation(er,HANDLE_FLAG_INHERIT,0);int nonInheritErrError=Marshal.GetLastWin32Error();if(!nonInheritOut||!nonInheritErr)throw new IOException("SetHandleInformation "+(!nonInheritOut?nonInheritOutError:nonInheritErrError));nul=CreateFile("NUL",GENERIC_READ,0,ref sa,OPEN_EXISTING,0,IntPtr.Zero);if(nul==new IntPtr(-1))throw new IOException("NUL "+Marshal.GetLastWin32Error());IntPtr bytes=IntPtr.Zero;bool sized=InitializeProcThreadAttributeList(IntPtr.Zero,1,0,ref bytes);int sizeError=Marshal.GetLastWin32Error();if(sized||sizeError!=122||bytes==IntPtr.Zero)throw new IOException("InitializeProcThreadAttributeList size "+sizeError);list=Marshal.AllocHGlobal(bytes);if(!InitializeProcThreadAttributeList(list,1,0,ref bytes))throw new IOException("InitializeProcThreadAttributeList "+Marshal.GetLastWin32Error());handles=Marshal.AllocHGlobal(IntPtr.Size*3);Marshal.WriteIntPtr(handles,0,ow);Marshal.WriteIntPtr(handles,IntPtr.Size,ew);Marshal.WriteIntPtr(handles,IntPtr.Size*2,nul);if(!UpdateProcThreadAttribute(list,0,new IntPtr(PROC_THREAD_ATTRIBUTE_HANDLE_LIST),handles,new IntPtr(IntPtr.Size*3),IntPtr.Zero,IntPtr.Zero))throw new IOException("UpdateProcThreadAttribute "+Marshal.GetLastWin32Error());var six=new SIX();six.StartupInfo.cb=Marshal.SizeOf(typeof(SIX));six.StartupInfo.dwFlags=(int)STARTF_USESTDHANDLES;six.StartupInfo.hStdOutput=ow;six.StartupInfo.hStdError=ew;six.StartupInfo.hStdInput=nul;six.lpAttributeList=list;PI pi;var cmd=new StringBuilder(Q(exe)+" "+String.Join(" ",Array.ConvertAll(args,Q)));if(!CreateProcess(null,cmd,IntPtr.Zero,IntPtr.Zero,true,CREATE_NEW_PROCESS_GROUP|EXTENDED_STARTUPINFO_PRESENT,IntPtr.Zero,null,ref six,out pi))throw new IOException("CreateProcessW "+Marshal.GetLastWin32Error());bool closedOut=CloseHandle(ow);int closeOutError=Marshal.GetLastWin32Error();bool closedErr=CloseHandle(ew);int closeErrError=Marshal.GetLastWin32Error();bool closedNul=CloseHandle(nul);int closeNulError=Marshal.GetLastWin32Error();ow=IntPtr.Zero;ew=IntPtr.Zero;nul=IntPtr.Zero;if(!closedOut||!closedErr||!closedNul){TerminateProcess(pi.hProcess,1);CloseHandle(pi.hThread);CloseHandle(pi.hProcess);throw new IOException("closing child-only handles "+(!closedOut?closeOutError:!closedErr?closeErrError:closeNulError));}var child=new M4Child(pi,or,er);transferred=true;return child;}finally{if(!transferred){if(or!=IntPtr.Zero)CloseHandle(or);if(er!=IntPtr.Zero)CloseHandle(er);}if(ow!=IntPtr.Zero)CloseHandle(ow);if(ew!=IntPtr.Zero)CloseHandle(ew);if(nul!=IntPtr.Zero&&nul!=new IntPtr(-1))CloseHandle(nul);if(list!=IntPtr.Zero){DeleteProcThreadAttributeList(list);Marshal.FreeHGlobal(list);}if(handles!=IntPtr.Zero)Marshal.FreeHGlobal(handles);}}
 M4Child(PI p,IntPtr o,IntPtr e){h=p.hProcess;CloseHandle(p.hThread);Pid=p.pid;ot=new Thread(()=>Drain(new FileStream(new Microsoft.Win32.SafeHandles.SafeFileHandle(o,true),FileAccess.Read),Out));et=new Thread(()=>Drain(new FileStream(new Microsoft.Win32.SafeHandles.SafeFileHandle(e,true),FileAccess.Read),Err));ot.Start();et.Start();}
 public bool Wait(int ms){return WaitForSingleObject(h,(uint)ms)==0;} public void FinishDrains(){if(!ot.Join(5000)||!et.Join(5000))throw new IOException("drain join timeout");if(overflow)throw new IOException("stdout/stderr exceeds 64KiB");if(readFailure)throw new IOException("stdout/stderr drain failed");} public string Stdout{get{lock(Out)return Out.ToString();}} public string Stderr{get{lock(Err)return Err.ToString();}} public int ExitCode{get{uint c;if(!GetExitCodeProcess(h,out c))throw new IOException();return unchecked((int)c);}}
 public bool CtrlBreak(){if(!SetConsoleCtrlHandler(IntPtr.Zero,true))throw new IOException("SetConsoleCtrlHandler ignore "+Marshal.GetLastWin32Error());try{bool ok=GenerateConsoleCtrlEvent(CTRL_BREAK_EVENT,(uint)Pid);if(!ok)throw new IOException("GenerateConsoleCtrlEvent "+Marshal.GetLastWin32Error());return true;}finally{if(!SetConsoleCtrlHandler(IntPtr.Zero,false))throw new IOException("SetConsoleCtrlHandler restore "+Marshal.GetLastWin32Error());}}
 public void Kill(){if(!TerminateProcess(h,1))throw new IOException("TerminateProcess "+Marshal.GetLastWin32Error());} public void Dispose(){IntPtr owned=Interlocked.Exchange(ref h,IntPtr.Zero);if(owned!=IntPtr.Zero&&!CloseHandle(owned))throw new IOException("CloseHandle(process) "+Marshal.GetLastWin32Error());}
}
'@ -ErrorAction Stop
function Start-Command([string[]]$argv){$p=[M4Child]::Start($Executable,$argv);[pscustomobject]@{Process=$p;argv=@($argv);started_utc=[datetime]::UtcNow.ToString('o');timeout_seconds=120}}
function RunArgsFor([string]$root,[string]$letter,[string]$size,[switch]$LongCheckpoint){@('run','--bundle',$root,'--size',$size,'--drive-letter',"$letter`:",'--checkpoint-seconds',$(if($LongCheckpoint){'86400'}else{$CheckpointSeconds}),'--checkpoint-dirty-mb',$(if($LongCheckpoint){'1048576'}else{$CheckpointDirtyMb}),'--ram-limit',$RamLimit)}
function Start-Run { Start-Command ([string[]](Args)) }
function Start-RunFor([string]$root,[string]$letter,[string]$size,[switch]$LongCheckpoint){Start-Command ([string[]](RunArgsFor $root $letter $size -LongCheckpoint:$LongCheckpoint))}
function Wait-ReadyFor($c,[string]$letter,[int]$seconds){$rx='(?m)^Ready: '+[regex]::Escape("$letter`:")+' generation ([1-9][0-9]*)\.$';$end=[datetime]::UtcNow.AddSeconds($seconds);do{$out=$c.Process.Stdout;if($out-match$rx){$g=[uint64]$Matches[1];$volume=Get-Volume -DriveLetter $letter -ErrorAction SilentlyContinue;$partition=Get-Partition -DriveLetter $letter -ErrorAction SilentlyContinue;$disk=$(if($partition){Get-Disk -Number $partition.DiskNumber -ErrorAction SilentlyContinue});if((Test-Path "$letter`:") -and $volume.FileSystem -eq 'NTFS' -and $disk.PartitionStyle -eq 'GPT'){return $g}};Start-Sleep -Milliseconds 100}while([datetime]::UtcNow-lt$end -and -not$c.Process.Wait(0));Block "ready/GPT/NTFS deadline; stdout=$($c.Process.Stdout); stderr=$($c.Process.Stderr)"}
function Wait-Ready($c,[int]$seconds){Wait-ReadyFor $c $DriveLetter $seconds}
function Latest-CheckpointText([string]$text){$best=$null;foreach($m in ([regex]'(?m)^Checkpoint committed generation ([0-9]+)\.$').Matches($text)){$value=[uint64]$m.Groups[1].Value;if($null-eq$best-or$value-gt$best.generation){$best=[pscustomobject]@{generation=$value;line=$m.Value}}};$best}
function Wait-Checkpoint($c,[uint64]$after){$end=[datetime]::UtcNow.AddSeconds(45);do{$best=Latest-CheckpointText $c.Process.Stdout;if($best-and$best.generation-gt$after){return $best};Start-Sleep -Milliseconds 100}while([datetime]::UtcNow-lt$end -and -not$c.Process.Wait(0));Block 'checkpoint successor was not observed'}
function CtrlC($c){Need ($c.Process.CtrlBreak()) 'GenerateConsoleCtrlEvent(CTRL_BREAK_EVENT, exact child group) failed';Need ($c.Process.Wait(60000)) 'clean shutdown deadline exceeded';$c.Process.FinishDrains();$exit=$c.Process.ExitCode;Need ($exit-eq 0) "clean shutdown exit=$exit; stdout=$($c.Process.Stdout); stderr=$($c.Process.Stderr)";$exit}
function CtrlC-FinalCheckpoint($c,[uint64]$after){$boundary=$c.Process.Stdout.Length;$exit=CtrlC $c;$all=$c.Process.Stdout;Need($all.Length-ge$boundary)'stdout shrank during shutdown';$suffix=$all.Substring($boundary);$final=Latest-CheckpointText $suffix;Need($final-and$final.generation-gt$after)'Ctrl+C did not emit a committed successor checkpoint';[pscustomobject]@{exit=$exit;checkpoint=$final;stdout_boundary=$boundary}}
function Emergency($c){$k=[ordered]@{pid=$c.Process.Pid;killed=$false;exit=$null};if(-not$c.Process.Wait(0)){$c.Process.Kill();Need($c.Process.Wait(10000))'emergency terminate wait failed';$k.killed=$true};$c.Process.FinishDrains();$k.exit=$c.Process.ExitCode;Need($k.exit-ne259)'emergency child remains STILL_ACTIVE';$k}
function Stop-Child($c){if(-not$c.Wait(0)){$c.Kill();Need($c.Wait(10000))'timed child terminate wait failed'};$c.FinishDrains()}
function Assert-AuditDescendants($events,[int]$rootPid){$desc=Descendants $events $rootPid;if(@($desc|?{[string]::IsNullOrWhiteSpace([string]$_.command_line)}).Count){throw 'audit descendant command line unavailable'};if(@($desc|?{$_.name-match'(?i)(powershell|provision|initialize-disk)' -or $_.command_line-match'(?i)(provision_volume|Initialize-Disk|New-Partition|Format-Volume)'}).Count){throw 'audit observed prohibited provisioning descendant'};$desc}
function Descendants($events,[int]$rootPid){$known=New-Object 'Collections.Generic.HashSet[int]';[void]$known.Add($rootPid);$result=New-Object Collections.ArrayList;$remaining=New-Object Collections.ArrayList;foreach($event in @($events)){[void]$remaining.Add($event)};do{$changed=$false;for($i=$remaining.Count-1;$i-ge0;$i--){$event=$remaining[$i];if($known.Contains([int]$event.parent_pid)){[void]$known.Add([int]$event.process_id);[void]$result.Add($event);$remaining.RemoveAt($i);$changed=$true}}}while($changed);@($result|Sort-Object timestamp)}
function Drain-ProcessEvents([string]$id,$events){Get-Event -SourceIdentifier $id -ErrorAction SilentlyContinue|%{$x=$_.SourceEventArgs.NewEvent;$proc=Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$x.ProcessID)" -ErrorAction SilentlyContinue;$null=$events.Add([ordered]@{name=[string]$x.ProcessName;parent_pid=[int]$x.ParentProcessID;process_id=[int]$x.ProcessID;command_line=[string]$proc.CommandLine;timestamp=[datetime]::UtcNow.ToString('o')});Remove-Event $_.EventIdentifier -ErrorAction SilentlyContinue}}
function Drain-ProcessEventsUntilQuiet([string]$id,$events){$deadline=[datetime]::UtcNow.AddSeconds(5);$quiet=0;do{$before=$events.Count;Drain-ProcessEvents $id $events;if($events.Count-eq$before){$quiet++}else{$quiet=0};if($quiet-lt3){Start-Sleep -Milliseconds 100}}while($quiet-lt3-and[datetime]::UtcNow-lt$deadline);Need($quiet-ge3)'process audit did not reach bounded quiescence'}
function Compact-Run { $c=[M4Child]::Start($Executable,[string[]]@('compact','--bundle',$Bundle));$start=[datetime]::UtcNow.ToString('o');try{if(-not$c.Wait(120000)){Stop-Child $c;throw 'compact timeout'};$c.FinishDrains();[ordered]@{argv=@('compact','--bundle',$Bundle);pid=$c.Pid;started_utc=$start;ended_utc=[datetime]::UtcNow.ToString('o');timeout_seconds=120;stdout=$c.Stdout;stderr=$c.Stderr;exit=$c.ExitCode}}finally{$c.Dispose()} }
function Native-SelfTest {
  $temp=Join-Path ([IO.Path]::GetTempPath()) ('myrd-m4-native-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $temp|Out-Null
  try {
    $shape=Inventory;foreach($required in @('boot_identity','drive_mappings','physical_devices')){Need($null-ne$shape.$required)"inventory contract missing $required"}
    $reverse=@([pscustomobject]@{name='powershell.exe';parent_pid=20;process_id=30;timestamp='2026-01-01T00:00:00Z'},[pscustomobject]@{name='cmd.exe';parent_pid=10;process_id=20;timestamp='2026-01-01T00:00:01Z'});Need(@(Descendants $reverse 10).Count-eq2)'descendant closure depended on event order'
    $immutable=Join-Path $temp 'immutable.json';Write-New $immutable 'first';$overwriteRejected=$false;try{Write-New $immutable 'second'}catch{$overwriteRejected=$true};Need($overwriteRejected-and[IO.File]::ReadAllText($immutable)-eq'first')'CreateNew evidence overwrite was accepted'
    $latest=Latest-CheckpointText "Checkpoint committed generation 4.`nCheckpoint committed generation 7.`n";Need($latest.generation-eq7-and$latest.line-eq'Checkpoint committed generation 7.')'latest checkpoint parser did not select the final committed generation'
    # argv contains a space, an embedded quote, and a trailing slash; the child
    # echoes all three and proves the native pipe drains/exit lifecycle.
    $probe=Join-Path $temp 'argv-probe.ps1';[IO.File]::WriteAllText($probe,'param($a,$b,$c) Write-Output $a; Write-Error $b; exit 0',[Text.UTF8Encoding]::new($false))
    $child=[M4Child]::Start((Get-Command powershell.exe).Source,[string[]]@('-NoProfile','-File',$probe,'space value','embedded"quote','trailing\'))
    Need ($child.Wait(15000)) 'native selftest timeout';$child.FinishDrains();Need ($child.ExitCode-eq0) 'native selftest exit';Need ($child.Out.ToString()-match'space value') 'native stdout drain/argv probe failed';Need ($child.Err.ToString()-match'embedded"quote') 'native stderr drain/argv probe failed';$child.Dispose();$child.Dispose()
    $overflow=Join-Path $temp 'overflow.ps1';[IO.File]::WriteAllText($overflow,'Write-Output (''x'' * 70000); exit 0',[Text.UTF8Encoding]::new($false));$large=[M4Child]::Start((Get-Command powershell.exe).Source,[string[]]@('-NoProfile','-File',$overflow));Need($large.Wait(15000))'native overflow selftest timeout';$overflowCaught=$false;try{$large.FinishDrains()}catch{$overflowCaught=$true}finally{$large.Dispose()};Need($overflowCaught)'native >64KiB overflow was accepted'
    $break=[M4Child]::Start($env:ComSpec,[string[]]@('/d','/c','ping -n 30 127.0.0.1 >nul'));Start-Sleep -Milliseconds 200;Need ($break.CtrlBreak()) 'native CTRL_BREAK selftest delivery failed';Need ($break.Wait(5000)) 'native CTRL_BREAK selftest timeout';$break.FinishDrains();$break.Dispose();$break.Dispose()
    $kill=[M4Child]::Start($env:ComSpec,[string[]]@('/d','/c','ping -n 30 127.0.0.1 >nul'));$wrapped=[pscustomobject]@{Process=$kill};$firstKill=Emergency $wrapped;$secondKill=Emergency $wrapped;Need($firstKill.killed-and-not$secondKill.killed)'emergency recheck contract failed';$kill.Dispose();$kill.Dispose()
    $timed=[M4Child]::Start($env:ComSpec,[string[]]@('/d','/c','ping -n 30 127.0.0.1 >nul'));Stop-Child $timed;Need($timed.Wait(0)-and$timed.ExitCode-ne259)'timed child cleanup left process active';$timed.Dispose()
    $missingCommand=@([pscustomobject]@{name='cmd.exe';parent_pid=10;process_id=20;command_line='';timestamp='2026-01-01T00:00:00Z'});$auditRejected=$false;try{Assert-AuditDescendants $missingCommand 10}catch{$auditRejected=$true};Need($auditRejected)'audit accepted descendant without command line'
    Write-Output 'M4 native harness selftest PASS';exit 0
  } finally {if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
}
if($env:MYRD_M4_HARNESS_SELFTEST-eq'1'){Native-SelfTest}
function Block-CleanupSelfTest {
  $temp=Join-Path ([IO.Path]::GetTempPath()) ('myrd-m4-block-cleanup-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $temp|Out-Null
  try {
    Need(-not[string]::IsNullOrWhiteSpace($env:MYRD_M4_BLOCK_CLEANUP_SENTINEL))'selftest cleanup sentinel was not supplied'
    $sentinel=[IO.Path]::GetFullPath($env:MYRD_M4_BLOCK_CLEANUP_SENTINEL)
    Need(-not(Test-Path -LiteralPath $sentinel))'selftest cleanup sentinel already exists'
    $child=[pscustomobject]@{Process=[M4Child]::Start((Get-Command powershell.exe).Source,[string[]]@('-NoProfile','-Command','Start-Sleep -Seconds 30'))}
    try { Block 'selftest forced block after child start.' }
    finally {
      try {$cleanup=Emergency $child}
      finally {$child.Process.Dispose()}
      if(-not($cleanup.killed-and$cleanup.exit-ne259-and$null-eq(Get-Process -Id $cleanup.pid -ErrorAction SilentlyContinue))){throw 'selftest cleanup did not terminate its exact child'}
      Write-New $sentinel 'cleaned'
      if([IO.File]::ReadAllText($sentinel)-ne'cleaned'){throw 'selftest cleanup sentinel missing'}
    }
  } finally {if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
}
if($env:MYRD_M4_BLOCK_CLEANUP_SELFTEST-eq'1'){Block-CleanupSelfTest}

$NegativeCases=@('unknown_nonempty','size_mismatch','occupied_letter','gen0','ambiguous_recovery','writer_lock','missing_driver','busy_volume','compact_lock')
$NegativeContracts=[ordered]@{
  unknown_nonempty=[ordered]@{fields=@('path','letter');expected_refusal='unknown_nonempty';exit=1}
  size_mismatch=[ordered]@{fields=@('path','letter','expected_size');expected_refusal='size_mismatch';exit=1}
  occupied_letter=[ordered]@{fields=@('path','letter','volume_guid');expected_refusal='occupied_letter';exit=1}
  gen0=[ordered]@{fields=@('path','letter','expected_size');expected_refusal='generation_zero';exit=1}
  ambiguous_recovery=[ordered]@{fields=@('path','letter','expected_size','sentinels','candidate_letters','candidate_volume_guids');expected_refusal='ambiguous_recovery';exit=1}
